// src/tools/cost-by-project.ts
var costByProject = tool({
  description: "opencode-sessions-explorer: aggregate OpenCode cost + token usage across sessions, grouped by project, directory, agent, or model. " + `Answers: "how much have I spent on OpenCode", "what's my OpenCode API spend by project", "cost breakdown by agent", "which directory burned the most tokens", "Claude Opus vs GPT cost comparison", "my biggest spending categories", "billing summary", "token usage by agent", "which model is most expensive for me", "OpenCode cost audit". ` + "group_by: 'project_id' (default), 'directory', 'agent', or 'model' (uses decoded session.model.id). " + "Returns: groups array (each: key, sessions count, cost, tokens.{input,output,reasoning,cache_read,cache_write}, cost_known flag) sorted by cost descending, plus a total summary. Optional since_ms/until_ms time window. " + "cost_known is false when ALL sessions in a group predate the session_usage migration \u2014 their `cost` column reads as 0 but isn't actually $0. " + "For TIME-SERIES (cost over time per period) use cost-by-period instead.",
  args: {
    group_by: tool.schema.enum(["project_id", "directory", "agent", "model"]).default("project_id"),
    since_ms: tool.schema.number().int().nonnegative().optional(),
    until_ms: tool.schema.number().int().nonnegative().optional(),
    archived: tool.schema.enum(["no", "only", "any"]).default("any"),
    min_cost: tool.schema.number().nonnegative().default(0.001).describe("Hide groups below this USD cost by default"),
    min_tokens: tool.schema.number().int().nonnegative().default(0).describe("Hide groups below this input+output token count"),
    top: tool.schema.number().int().min(1).max(50).default(20)
  },
  async execute(args) {
    return runWithEnvelope("cost_by_project", 32, async () => {
      const where = [];
      const params = [];
      if (args.since_ms !== undefined) {
        where.push("time_created >= ?");
        params.push(args.since_ms);
      }
      if (args.until_ms !== undefined) {
        where.push("time_created <= ?");
        params.push(args.until_ms);
      }
      if (args.archived === "no")
        where.push("time_archived IS NULL");
      else if (args.archived === "only")
        where.push("time_archived IS NOT NULL");
      const whereSql = where.length ? "WHERE " + where.join(" AND ") : "";
      const keyExpr = args.group_by === "model" ? "COALESCE(json_extract(model,'$.id'), 'unknown')" : args.group_by === "directory" ? "directory" : args.group_by === "agent" ? "COALESCE(agent, 'unknown')" : "project_id";
      const having = [];
      if (args.min_cost > 0)
        having.push("SUM(cost) >= ?");
      if (args.min_tokens > 0)
        having.push("(SUM(tokens_input) + SUM(tokens_output)) >= ?");
      const sql = `
        SELECT ${keyExpr} AS key,
               COUNT(*) AS sessions,
               ROUND(SUM(cost), 6) AS cost,
               SUM(tokens_input) AS tokens_input,
               SUM(tokens_output) AS tokens_output,
               SUM(tokens_reasoning) AS tokens_reasoning,
               SUM(tokens_cache_read) AS tokens_cache_read,
               SUM(tokens_cache_write) AS tokens_cache_write,
               SUM(CASE WHEN cost > 0 OR tokens_input > 0 THEN 1 ELSE 0 END) AS known_count,
               MIN(time_created) AS first_ts,
               MAX(time_updated) AS last_ts
          FROM session_v2
          ${whereSql}
       GROUP BY key
       ${having.length ? "HAVING " + having.join(" AND ") : ""}
       ORDER BY cost DESC
          LIMIT ?`;
      if (args.min_cost > 0)
        params.push(args.min_cost);
      if (args.min_tokens > 0)
        params.push(args.min_tokens);
      params.push(args.top ?? 20);
      const rows = stmt(sql).all(...params);
      const records = rows.map((r) => ({
        key: r.key,
        sessions: Number(r.sessions),
        cost: Number(r.cost ?? 0),
        cost_known: Number(r.known_count) > 0,
        tokens_input: Number(r.tokens_input ?? 0),
        tokens_output: Number(r.tokens_output ?? 0),
        tokens_reasoning: Number(r.tokens_reasoning ?? 0),
        tokens_cache_read: Number(r.tokens_cache_read ?? 0),
        tokens_cache_write: Number(r.tokens_cache_write ?? 0),
        first_ts: Number(r.first_ts),
        last_ts: Number(r.last_ts)
      }));
      const totalSessions = records.reduce((a, g) => a + g.sessions, 0);
      const total = {
        sessions: totalSessions,
        cost: Number(records.reduce((a, g) => a + g.cost, 0).toFixed(6)),
        tokens_input: records.reduce((a, g) => a + g.tokens_input, 0),
        tokens_output: records.reduce((a, g) => a + g.tokens_output, 0),
        cost_known_pct: totalSessions === 0 ? 0 : Number((records.reduce((a, g) => a + (g.cost_known ? g.sessions : 0), 0) / totalSessions).toFixed(4))
      };
      return { group_by: args.group_by, filters: { min_cost: args.min_cost, min_tokens: args.min_tokens }, groups: table(records), total };
    });
  }
});

